		}

		/*
		 * The staging canvas must stay laid out and painted for the experimental draw to read a cached paint record, so it lives in a clipped one-by-one container rather than display:none.
		 * It is absolutely positioned at the container origin and overflows it; overflow:hidden clips it to one pixel while the browser still lays it out and paints it.
		 */
		.staging-container {
			position: absolute;
			right: 0;
			bottom: 0;
			width: 1px;
			height: 1px;
