	/**
	 * Resolves the page theme before the first render so the host reflects `data-room-theme` from the start, and the monitor form is captured in the page's palette rather than flashing the light form first.
	 *
	 * On a reconnect it also re-runs {@link setUp}: the shadow DOM survives a re-parenting, so `hasUpdated` stays true, `firstUpdated` never fires again, and the wiring {@link tearDown} removed has to come back here, with the `@query` fields still resolving into the kept shadow root.
	 */
	connectedCallback(): void {
		super.connectedCallback();
		this.theme = this.detectTheme();

		if ( this.hasUpdated ) {
			this.setUp();
		}
	}

	/**
	 * Runs the shared {@link setUp} once the viewport canvas exists after the first render.
	 */
	protected firstUpdated(): void {
		this.setUp();
	}

	/**
	 * Builds the scene, wires the controls, observers, and theme listeners, starts the repaint timers, and kicks the loop.
	 *
	 * It is shared by `firstUpdated` and a reconnect, because `firstUpdated` only ever fires once: without `connectedCallback` re-running this, a room moved to a new parent would come back looking navigable but dead, with everything {@link tearDown} released still gone.
	 * The `isSetUp` guard keeps the two entry points from wiring the room twice.
	 * It also refuses to wire a detached element: an append and remove in the same task still runs the pending first update after disconnection, and the document and window listeners wired here would never hear the disconnect that already happened.
	 * The theme is already resolved on connect, so the scene and the monitor form open in the page's palette.
	 */
	private setUp(): void {
		if ( this.isSetUp || ! this.isConnected ) {
			return;
		}

		this.isSetUp = true;
		this.resolveTextureMode();
		this.initScene();
		this.bindEvents();
		this.bindThemeListeners();
		this.observeDevicePixelRatio();
		this.startContentTimers();
		this.prevTime = performance.now();
		this.startLoop();
	}

	/**
	 * Tears the room down through the shared {@link tearDown} when it leaves the document.
	 */
	disconnectedCallback(): void {
		super.disconnectedCallback();
		this.tearDown();
	}

	/**
	 * Stops the loop and tears down every timer, listener, observer, every scene geometry and material, and the WebGL context so a removed room leaks nothing.
	 *
	 * It is the mirror of {@link setUp} rather than the body of `disconnectedCallback`, so a reconnected room can rebuild exactly what this released; clearing `isSetUp` is what re-arms that rebuild.
	 * The gesture, key, lock, and focus state is reset alongside the wiring, because the listeners that would have released a held key or an active drag are removed here and can never deliver those events to a detached room.
	 * The live surfaces are emptied, not just disposed, so a reconnect's rebuilt monitor does not sit beside a dead entry the loop would keep uploading.
	 */
	private tearDown(): void {
		this.isSetUp = false;
		this.stopLoop();

		for ( const id of this.timers ) {
			clearInterval( id );
		}

		this.timers.length = 0;
		this.resizeObserver?.disconnect();
		this.resizeObserver = null;
		this.intersectionObserver?.disconnect();
		this.intersectionObserver = null;
		this.dprQuery?.removeEventListener( 'change', this.onDevicePixelRatioChange );
		this.dprQuery = null;
		this.themeMedia?.removeEventListener( 'change', this.onThemeMediaChange );
		this.themeMedia = null;
		this.themeObserver?.disconnect();
		this.themeObserver = null;
		this.renderRoot.removeEventListener( 'keydown', this.onKeyDown );
		this.renderRoot.removeEventListener( 'keyup', this.onKeyUp );
		document.removeEventListener( 'pointerlockchange', this.onPointerLockChange );
		document.removeEventListener( 'pointermove', this.onPointerMove );
		window.removeEventListener( 'pointerup', this.onPointerUp );
		window.removeEventListener( 'pointercancel', this.onPointerCancel );
		this.$viewport?.removeEventListener( 'pointerdown', this.onPointerDown );
		this.$viewport?.removeEventListener( 'click', this.onViewportClick );

		for ( const code of MOVEMENT_KEYS ) {
			this.keys[ code ] = false;
		}

		this.isDragging = false;
		this.activePointerId = null;
		this.isLocked = false;
		this.$interactiveTarget = null;

		for ( const surface of this.surfaces ) {
			surface.staging.onpaint = null;
			surface.texture.dispose();
		}

		this.surfaces = [];
		this.placeholderSurface?.texture.dispose();
		this.placeholderSurface = null;
		this.disposeScene();
		this.renderer?.dispose();
		this.scene = null;
		this.camera = null;
		this.renderer = null;
		this.monitorMesh = null;
	}

	/**
	 * Disposes every geometry and material the room built, walking the scene graph so the floor, rug, ceiling, walls, baseboards, desk, legs, and the monitor, bezel, and stand are all freed.
	 *
	 * It traverses the scene rather than the kept material handles because the geometries and the untracked leg, bezel, and monitor-screen materials are never held in a field, and `renderer.dispose()` releases the renderer's own state but not the meshes' GPU buffers; the monitor's `CanvasTexture` is already disposed above, and a second `.map` dispose is not needed.
	 */
	private disposeScene(): void {
		this.scene?.traverse( ( object ) => {
			if ( ! ( object instanceof THREE.Mesh ) ) {
				return;
			}

			object.geometry.dispose();
			const material = object.material;

			if ( Array.isArray( material ) ) {
				for ( const entry of material ) {
					entry.dispose();
				}
			} else {
				material.dispose();
			}
		} );
	}

	/**
	 * The render root used as the script's `root`, so DOM lookups, hit testing, and the locked-element check stay inside the shadow boundary.
	 *
	 * A Lit shadow root is a `DocumentOrShadowRoot`, so it answers `getElementById`, `querySelectorAll`, and `pointerLockElement` the way a standalone reference expected `document` to.
	 * The component always renders into a shadow root, so the `instanceof` narrows `renderRoot` to `ShadowRoot` without a cast, and the throw is the honest fallback for the impossible light-DOM case.
	 */
	private get root(): ShadowRoot {
		if ( this.renderRoot instanceof ShadowRoot ) {
			return this.renderRoot;
		}

		throw new Error( 'configurator-3d-room expected a shadow root' );
	}

	/**
	 * Records whether the monitor can be live HTML, through the shared {@link supportsHtmlInCanvas} predicate that feature-detects `drawElementImage` on a live 2D context rather than sniffing a UA string.
	 */
	private resolveTextureMode(): void {
		this.textureMode = supportsHtmlInCanvas() ? 'live' : 'placeholder';
	}

	/**
	 * Resolves the page theme the same way the demo page decides it: an explicit `data-theme` on the document element wins, and the OS color scheme is the fallback when nothing is pinned.
	 *
	 * The demo page writes `data-theme` from a saved preference or `prefers-color-scheme` on load, so reading that attribute first keeps the room in step with an in-page toggle, and the media-query fallback covers the bare case where the attribute is absent.
	 *
	 * @returns The theme the room should render for right now.
	 */
	private detectTheme(): RoomTheme {
		const pinned = document.documentElement.dataset.theme;

		if ( pinned === 'dark' || pinned === 'light' ) {
			return pinned;
		}

		return window.matchMedia( '(prefers-color-scheme: dark)' ).matches ? 'dark' : 'light';
	}

	/**
	 * The palette for the current theme, the single object both the scene materials and the monitor-form painter read.
	 */
	private get palette(): RoomPalette {
		return ROOM_PALETTES[ this.theme ];
	}

	/**
	 * Wires the two ways the page theme can change at runtime: the OS color scheme and an in-page `data-theme` toggle.
	 *
	 * The media-query listener follows a system theme switch when nothing is pinned, and the mutation observer follows a toggle that writes `data-theme` on the document element; both funnel through {@link refreshTheme} so a change re-themes the scene and the form from one place.
	 */
	private bindThemeListeners(): void {
		this.themeMedia = window.matchMedia( '(prefers-color-scheme: dark)' );
		this.themeMedia.addEventListener( 'change', this.onThemeMediaChange );

		this.themeObserver = new MutationObserver( () => this.refreshTheme() );
		this.themeObserver.observe( document.documentElement, { attributes: true, attributeFilter: [ 'data-theme' ] } );
	}

	/**
	 * Re-resolves the OS color scheme into the room when the system theme flips.
	 */
	private onThemeMediaChange = (): void => {
		this.refreshTheme();
	};

	/**
	 * Re-resolves the theme and, when it actually changed, recolors the scene and repaints the monitor so the room follows the page.
	 *
	 * It is a no-op when the resolved theme is unchanged, so an unrelated `data-theme` mutation or a media event that does not cross the light-dark boundary costs nothing.
	 */
	private refreshTheme(): void {
		const next = this.detectTheme();

		if ( next === this.theme ) {
			return;
		}

		this.theme = next;
		this.applyTheme();
	}

	/**
	 * Pushes the current palette onto the live scene: the background, every themed material, the lights, and the static monitor placeholder, so a runtime theme change lands without rebuilding the room.
	 *
	 * The live monitor form re-themes through its own CSS off the reflected `data-room-theme` attribute, so this only needs to repaint the static placeholder; a `requestPaint` keeps the live path's caption and caret current too.
	 */
	private applyTheme(): void {
		const palette = this.palette;

		if ( this.scene ) {
			this.scene.background = new THREE.Color( palette.background );
		}

		this.themedMaterials.floor?.color.setHex( palette.floor );
		this.themedMaterials.rug?.color.setHex( palette.rug );
		this.themedMaterials.ceiling?.color.setHex( palette.ceiling );
		this.themedMaterials.baseboard?.color.setHex( palette.baseboard );
		this.themedMaterials.desk?.color.setHex( palette.desk );

		for ( const wall of this.themedMaterials.walls ) {
			wall.color.setHex( palette.wall );
		}

		if ( this.themedLights.ambient ) {
			this.themedLights.ambient.intensity = palette.ambient;
		}

		if ( this.themedLights.hemisphere ) {
			this.themedLights.hemisphere.intensity = palette.hemisphere;
			this.themedLights.hemisphere.color.setHex( palette.hemisphereSky );
			this.themedLights.hemisphere.groundColor.setHex( palette.hemisphereGround );
		}

		for ( const fill of this.themedLights.fills ) {
			fill.color.setHex( palette.fillColor );
			fill.intensity = palette.fillIntensity;
		}

		this.repaintMonitorPlaceholder();
		this.$monitorCanvas.requestPaint?.();
		this.requestRender();
	}

	/**
	 * Repaints the static monitor placeholder in the current palette, used after a theme change so the fallback screen matches the dark room.
	 *
	 * It only does work on the placeholder path, where a single surface backs the monitor with a painted mirror; on the live path the form is captured from the DOM and re-themes through CSS, so there is nothing to repaint here.
	 */
	private repaintMonitorPlaceholder(): void {
		const monitor = this.placeholderSurface;

		if ( ! monitor ) {
			return;
		}

		this.paintMonitorPlaceholder( monitor.ctx, monitor.mirror.width, monitor.mirror.height );
		monitor.texture.needsUpdate = true;
	}

	/**
	 * The current size of the viewport canvas in CSS pixels, read from the element rather than the window so it is right in both standalone and embedded contexts.
	 */
	private viewportSize(): { width: number; height: number } {
		return {
			width: this.$viewport.clientWidth || 1,
			height: this.$viewport.clientHeight || 1,
		};
	}

	/**
	 * Creates the scene, camera, renderer, room geometry, the desk, the monitor surface, and the lighting, then frames the camera on the monitor.
	 */
	private initScene(): void {
		const palette = this.palette;
		const scene = new THREE.Scene();
		scene.background = new THREE.Color( palette.background );
		this.scene = scene;

		const size = this.viewportSize();
		const camera = new THREE.PerspectiveCamera( 60, size.width / size.height, 0.01, 100 );

		// Stand a couple of metres back from the back-wall monitor, eye height, looking straight at the screen so the form is framed and readable on load.
		camera.position.set( 0, 1.7, 0.4 );
		camera.lookAt( 0, 1.78, -HALF_D );
		this.camera = camera;

		const renderer = new THREE.WebGLRenderer( { canvas: this.$viewport, antialias: true } );
		renderer.setSize( size.width, size.height, false );
		renderer.setPixelRatio( Math.min( window.devicePixelRatio, 2 ) );
		renderer.toneMapping = THREE.ACESFilmicToneMapping;
		renderer.toneMappingExposure = 1.05;
		this.renderer = renderer;

		this.buildRoom( scene );
		this.buildDesk( scene );
		this.buildMonitor( scene );
		this.buildLighting( scene );
	}

	/**
	 * Builds the floor, rug, ceiling, four walls, and baseboards from the current palette, and keeps each material so a theme change can recolor it.
	 *
	 * In the light theme every large surface is a white or very light neutral so the room reads as a clean, well-lit office; in the dark theme the same surfaces drop to lifted dark neutrals so the room reads as a dim evening office while the monitor still stands out against the wall.
	 *
	 * @param scene - The scene to add the room shell to.
	 */
	private buildRoom( scene: THREE.Scene ): void {
		const palette = this.palette;

		const floorMat = new THREE.MeshStandardMaterial( { color: palette.floor, roughness: 0.85, metalness: 0.02 } );
		const floor = new THREE.Mesh( new THREE.PlaneGeometry( ROOM_W, ROOM_D ), floorMat );
		floor.rotation.x = -Math.PI / 2;
		scene.add( floor );
		this.themedMaterials.floor = floorMat;

		const rugMat = new THREE.MeshStandardMaterial( { color: palette.rug, roughness: 0.95 } );
		const rug = new THREE.Mesh( new THREE.PlaneGeometry( 4.5, 3.5 ), rugMat );
		rug.rotation.x = -Math.PI / 2;
		rug.position.set( 0, 0.005, -0.4 );
		scene.add( rug );
		this.themedMaterials.rug = rugMat;

		const ceilingMat = new THREE.MeshStandardMaterial( { color: palette.ceiling, roughness: 0.95 } );
		const ceiling = new THREE.Mesh( new THREE.PlaneGeometry( ROOM_W, ROOM_D ), ceilingMat );
		ceiling.rotation.x = Math.PI / 2;
		ceiling.position.y = ROOM_H;
		scene.add( ceiling );
		this.themedMaterials.ceiling = ceilingMat;

		const wallMat = new THREE.MeshStandardMaterial( { color: palette.wall, roughness: 0.9, metalness: 0.02 } );

		const backWall = new THREE.Mesh( new THREE.PlaneGeometry( ROOM_W, ROOM_H ), wallMat );
		backWall.position.set( 0, ROOM_H / 2, -HALF_D );
		scene.add( backWall );

		const frontWallMat = wallMat.clone();
		const frontWall = new THREE.Mesh( new THREE.PlaneGeometry( ROOM_W, ROOM_H ), frontWallMat );
		frontWall.position.set( 0, ROOM_H / 2, HALF_D );
		frontWall.rotation.y = Math.PI;
		scene.add( frontWall );

		const leftWallMat = wallMat.clone();
		const leftWall = new THREE.Mesh( new THREE.PlaneGeometry( ROOM_D, ROOM_H ), leftWallMat );
		leftWall.position.set( -HALF_W, ROOM_H / 2, 0 );
		leftWall.rotation.y = Math.PI / 2;
		scene.add( leftWall );

		const rightWallMat = wallMat.clone();
		const rightWall = new THREE.Mesh( new THREE.PlaneGeometry( ROOM_D, ROOM_H ), rightWallMat );
		rightWall.position.set( HALF_W, ROOM_H / 2, 0 );
		rightWall.rotation.y = -Math.PI / 2;
		scene.add( rightWall );

		this.themedMaterials.walls = [ wallMat, frontWallMat, leftWallMat, rightWallMat ];

		const baseMat = new THREE.MeshStandardMaterial( { color: palette.baseboard, roughness: 0.8 } );
		const addBaseboard = ( width: number, x: number, z: number, rotY: number ): void => {
			const mesh = new THREE.Mesh( new THREE.BoxGeometry( width, 0.1, 0.03 ), baseMat );
			mesh.position.set( x, 0.05, z );
			mesh.rotation.y = rotY;
			scene.add( mesh );
		};

		addBaseboard( ROOM_W, 0, -HALF_D + 0.015, 0 );
		addBaseboard( ROOM_W, 0, HALF_D - 0.015, 0 );
		addBaseboard( ROOM_D, -HALF_W + 0.015, 0, Math.PI / 2 );
		addBaseboard( ROOM_D, HALF_W - 0.015, 0, Math.PI / 2 );
		this.themedMaterials.baseboard = baseMat;
	}

	/**
	 * Builds the desk top and its four legs under the monitor.
	 *
	 * @param scene - The scene to add the desk to.
	 */
	private buildDesk( scene: THREE.Scene ): void {
		const deskMat = new THREE.MeshStandardMaterial( { color: this.palette.desk, roughness: 0.6, metalness: 0.1 } );
		const deskTop = new THREE.Mesh( new THREE.BoxGeometry( 3, 0.08, 0.9 ), deskMat );
		deskTop.position.set( 0, 0.8, -3.55 );
		scene.add( deskTop );
		this.themedMaterials.desk = deskMat;

		const legMat = new THREE.MeshStandardMaterial( { color: 0xb7b7b1, roughness: 0.5, metalness: 0.3 } );
		const legGeo = new THREE.BoxGeometry( 0.06, 0.8, 0.06 );
		const legPositions: ReadonlyArray<[ number, number, number ]> = [
			[ -1.4, 0.4, -3.9 ],
			[ 1.4, 0.4, -3.9 ],
			[ -1.4, 0.4, -3.2 ],
			[ 1.4, 0.4, -3.2 ],
		];

		for ( const [ x, y, z ] of legPositions ) {
			const leg = new THREE.Mesh( legGeo, legMat );
			leg.position.set( x, y, z );
			scene.add( leg );
		}
	}

	/**
	 * Builds the monitor with its texture, bezel, and stand on the back-wall desk.
	 *
	 * On the live path the screen gets a `THREE.CanvasTexture` backed by a mirror of the form's staging canvas; on the placeholder path it gets a static painted texture so the screen is never blank.
	 *
	 * @param scene - The scene to add the monitor to.
	 */
	private buildMonitor( scene: THREE.Scene ): void {
		const monitorTexture = this.makeSurfaceTexture( this.$monitorCanvas, 760, 488, ( ctx, w, h ) => this.paintMonitorPlaceholder( ctx, w, h ) );

		const bezelMat = new THREE.MeshStandardMaterial( { color: 0x2a2a30, roughness: 0.35, metalness: 0.7 } );

		const monitorBezel = new THREE.Mesh( new THREE.BoxGeometry( 2.62, 1.74, 0.06 ), bezelMat );
		monitorBezel.position.set( 0, 1.78, -3.97 );
		scene.add( monitorBezel );

		const monitorMesh = new THREE.Mesh(
			new THREE.PlaneGeometry( 2.46, 1.58 ),
			new THREE.MeshBasicMaterial( { map: monitorTexture } ),
		);
		monitorMesh.position.set( 0, 1.78, -3.93 );
		scene.add( monitorMesh );
		this.monitorMesh = monitorMesh;

		const stand = new THREE.Mesh( new THREE.BoxGeometry( 0.15, 0.2, 0.15 ), bezelMat );
		stand.position.set( 0, 0.94, -3.7 );
		scene.add( stand );

		const standBase = new THREE.Mesh( new THREE.BoxGeometry( 0.5, 0.04, 0.3 ), bezelMat );
		standBase.position.set( 0, 0.84, -3.6 );
		scene.add( standBase );
	}

	/**
	 * Makes the texture for the monitor, wiring the live capture path when supported and painting a static placeholder otherwise.
	 *
	 * On the live path it registers the staging canvas's `onpaint` to draw its HTML child, kicks an initial paint, and records a {@link StagingSurface} so the loop copies the staging bitmap into the mirror each frame.
	 * On the placeholder path it paints the supplied static scene into the mirror once, so the screen still shows the form with no experimental API.
	 *
	 * @param $staging - The `layoutsubtree` staging canvas hosting the form HTML.
	 * @param width - The texture width in pixels.
	 * @param height - The texture height in pixels.
	 * @param paintPlaceholder - Paints the static fallback into a 2D context.
	 * @returns The texture mapped onto the monitor.
	 */
	private makeSurfaceTexture(
		$staging: HTMLCanvasElement,
		width: number,
		height: number,
		paintPlaceholder: ( ctx: CanvasRenderingContext2D, width: number, height: number ) => void,
	): THREE.CanvasTexture {
		const $mirror = document.createElement( 'canvas' );
		$mirror.width = width;
		$mirror.height = height;
		const mirrorCtx = $mirror.getContext( '2d' );

		const texture = new THREE.CanvasTexture( $mirror );
		texture.minFilter = THREE.LinearFilter;
		texture.magFilter = THREE.LinearFilter;
		texture.generateMipmaps = false;
		texture.colorSpace = THREE.SRGBColorSpace;

		if ( ! mirrorCtx ) {
			return texture;
		}

		if ( this.textureMode === 'live' ) {
			const $content = $staging.firstElementChild;
			const stagingCtx = $staging.getContext( '2d' );

			if ( $content && stagingCtx ) {
				$staging.layoutSubtree = true;
				$staging.onpaint = (): void => {
					stagingCtx.clearRect( 0, 0, $staging.width, $staging.height );
					stagingCtx.drawElementImage( $content, 0, 0 );

					// The staging bitmap just changed, so the gated loop owes one frame to copy it into the mirror and re-upload the texture; this is the only signal the live monitor gives.
					this.requestRender();
				};
				$staging.requestPaint();
				this.surfaces.push( { staging: $staging, mirror: $mirror, mirrorCtx, texture } );
				return texture;
			}
		}

		paintPlaceholder( mirrorCtx, width, height );
		texture.needsUpdate = true;
		this.placeholderSurface = { mirror: $mirror, ctx: mirrorCtx, texture };
		return texture;
	}

	/**
	 * Paints the static monitor placeholder, a sign-up panel that mirrors the live form so the screen reads as the same control even without the experimental API, in the current theme's palette.
	 *
	 * The light theme paints a white panel and the dark theme a dark one with light text, matching the live form's two palettes, and the layout is sized to sit inside the 760 by 488 screen with margin rather than spilling onto the bezel.
	 *
	 * @param ctx - The mirror context to paint into.
	 * @param width - The texture width.
	 * @param height - The texture height.
	 */
	private paintMonitorPlaceholder( ctx: CanvasRenderingContext2D, width: number, height: number ): void {
		const dark = this.theme === 'dark';
		const colors = dark
			? { top: '#17171c', bottom: '#1f1f25', accent: '#6f9bff', title: '#ededf0', label: '#9a9aa5', inputFill: '#222228', inputBorder: '#34343c', inputText: '#ededf0', button: '#3f6fe0' }
			: { top: '#ffffff', bottom: '#eef1f6', accent: '#2257e6', title: '#17171a', label: '#6a6a76', inputFill: '#ffffff', inputBorder: '#d6d8df', inputText: '#17171a', button: '#2257e6' };

		const gradient = ctx.createLinearGradient( 0, 0, 0, height );
		gradient.addColorStop( 0, colors.top );
		gradient.addColorStop( 1, colors.bottom );
		ctx.fillStyle = gradient;
		ctx.fillRect( 0, 0, width, height );

		// The live form sits in a centered column capped at 380px, half of the 760px monitor content width, so the painted fallback derives the same column here and centers it inside the padded content box, rather than running the fields and button at the old near-full width that overflowed to the right.
		const contentPadding = 46;
		const contentLeft = contentPadding;
		const contentWidth = width - contentPadding * 2;
		const columnWidth = Math.min( 380, contentWidth / 2 );
		const columnX = contentLeft + ( contentWidth - columnWidth ) / 2;
		const textInset = 15;

		ctx.fillStyle = colors.accent;
		ctx.font = '700 20px Inter, system-ui, sans-serif';
		ctx.fillText( 'SIGN UP', columnX, 70 );

		ctx.fillStyle = colors.title;
		ctx.font = '800 34px Inter, system-ui, sans-serif';
		ctx.fillText( 'Drop us a note', columnX, 112 );

		const fields: ReadonlyArray<[ string, string ]> = [
			[ 'YOUR NAME', 'Jane Doe' ],
			[ 'EMAIL', 'jane@example.com' ],
			[ 'WHAT IS ON YOUR MIND?', 'HTML-in-Canvas feedback' ],
		];

		let y = 156;
		for ( const [ label, value ] of fields ) {
			ctx.fillStyle = colors.label;
			ctx.font = '700 12px Inter, system-ui, sans-serif';
			ctx.fillText( label, columnX, y );

			ctx.fillStyle = colors.inputFill;
			ctx.strokeStyle = colors.inputBorder;
			ctx.lineWidth = 1;
			this.roundRect( ctx, columnX, y + 9, columnWidth, 40, 9 );
			ctx.fill();
			ctx.stroke();

			// The live fields now start empty with placeholder hints, so the painted fallback dims its sample values to read as the same placeholders.
			ctx.fillStyle = colors.inputText;
			ctx.globalAlpha = 0.55;
			ctx.font = '15px Inter, system-ui, sans-serif';
			ctx.fillText( value, columnX + textInset, y + 34 );
			ctx.globalAlpha = 1;
			y += 76;
		}

		ctx.fillStyle = colors.button;
		this.roundRect( ctx, columnX, y + 2, columnWidth, 46, 9 );
		ctx.fill();
		ctx.fillStyle = '#ffffff';
		ctx.font = '700 16px Inter, system-ui, sans-serif';
		ctx.fillText( 'Save configuration', columnX + textInset, y + 31 );
	}

	/**
	 * Strokes a rounded rectangle path for the placeholder fields, since the 2D context has no rounded-rect fill shorthand on every build.
	 *
	 * @param ctx - The context to draw the path into.
	 * @param x - The left edge.
	 * @param y - The top edge.
	 * @param width - The rectangle width.
	 * @param height - The rectangle height.
	 * @param radius - The corner radius.
	 */
	private roundRect( ctx: CanvasRenderingContext2D, x: number, y: number, width: number, height: number, radius: number ): void {
		ctx.beginPath();
		ctx.moveTo( x + radius, y );
		ctx.arcTo( x + width, y, x + width, y + height, radius );
		ctx.arcTo( x + width, y + height, x, y + height, radius );
		ctx.arcTo( x, y + height, x, y, radius );
		ctx.arcTo( x, y, x + width, y, radius );
		ctx.closePath();
	}

	/**
	 * Lights the studio from the current palette: an ambient base, a hemisphere bounce, and two soft ceiling fills, each kept so a theme change can dim or warm it.
	 *
	 * In the light theme the lighting is strong and neutral so the white office reads as one even light with no muddy shadows; in the dark theme the same rig is dimmer and warmer so the room reads as a softly lit evening office that is still clearly legible rather than a black box.
	 *
	 * @param scene - The scene to light.
	 */
	private buildLighting( scene: THREE.Scene ): void {
		const palette = this.palette;

		const ambient = new THREE.AmbientLight( 0xffffff, palette.ambient );
		scene.add( ambient );
		this.themedLights.ambient = ambient;

		const hemisphere = new THREE.HemisphereLight( palette.hemisphereSky, palette.hemisphereGround, palette.hemisphere );
		scene.add( hemisphere );
		this.themedLights.hemisphere = hemisphere;

		const frontFill = new THREE.PointLight( palette.fillColor, palette.fillIntensity, 26 );
		frontFill.position.set( 0, 3.2, 2.2 );
		scene.add( frontFill );

		const backFill = new THREE.PointLight( palette.fillColor, palette.fillIntensity, 26 );
		backFill.position.set( 0, 3.2, -2.4 );
		scene.add( backFill );

		this.themedLights.fills = [ frontFill, backFill ];
	}

	/**
	 * Wires keyboard, pointer-lock, pointer, click, resize, and intersection listeners.
	 *
	 * Movement keys listen on the render root rather than `document` so the room only steers while it has keyboard focus: the demo runs in a `LiveExample` iframe, and a `document` listener never fires unless the iframe holds focus, while a render-root listener catches keystrokes from the focused viewport canvas when walking and from a focused monitor field when typing, yet stays silent when the reader's focus is anywhere else on the page, so the room never hijacks the page keyboard.
	 * Pointer-lock changes and captured or dragged pointer motion are still delivered at the document and window level, so `pointerlockchange`, `pointermove`, and the releasing `pointerup` and `pointercancel` stay there; the look handler self-gates on lock or an owned drag, so it does nothing until the reader is interacting, and a drag that leaves the canvas keeps looking.
	 * The resize observer watches the viewport so the renderer tracks the embedded stage, and the intersection observer pauses the loop when the demo scrolls offscreen.
	 */
	private bindEvents(): void {
		this.renderRoot.addEventListener( 'keydown', this.onKeyDown );
		this.renderRoot.addEventListener( 'keyup', this.onKeyUp );
		document.addEventListener( 'pointerlockchange', this.onPointerLockChange );
		document.addEventListener( 'pointermove', this.onPointerMove );
		window.addEventListener( 'pointerup', this.onPointerUp );
		window.addEventListener( 'pointercancel', this.onPointerCancel );

		this.$viewport.addEventListener( 'pointerdown', this.onPointerDown );
		this.$viewport.addEventListener( 'click', this.onViewportClick );

		this.resizeObserver = new ResizeObserver( () => this.onResize() );
		this.resizeObserver.observe( this.$viewport );

		this.intersectionObserver = new IntersectionObserver(
			( entries ) => this.onIntersection( entries ),
			{ threshold: 0.01 },
		);
		this.intersectionObserver.observe( this.$viewport );
	}

	/**
	 * Whether a key code should drive movement right now.
	 *
	 * While a form field is focused every key belongs to the field, arrows included, because a caret that cannot move is a broken input while a room that pauses walking mid-type is just polite.
	 * Steering resumes the moment the field blurs, which Escape or a click away from the monitor does.
	 *
	 * @param code - The keyboard event code.
	 * @returns Whether the code should be treated as a movement key.
	 */
	private isMovementKey( code: string ): boolean {
		if ( ! MOVEMENT_KEYS.has( code ) ) {
			return false;
		}

		return ! this.$interactiveTarget;
	}

	/**
	 * Records a held movement key, and treats Escape as the single release: it blurs any focused field and frees a captured cursor.
	 *
	 * The browser already exits pointer lock on Escape, but when a form field is focused the keystroke is delivered to the field, so the handler blurs the field and calls `exitPointerLock` itself, so one Escape both stops typing and hands the cursor back rather than needing two presses.
	 * The parameter is typed `Event` rather than `KeyboardEvent` so the handler satisfies the render root's `EventTarget.addEventListener` listener type, since a shadow root carries no typed keyboard-event overload; it is narrowed to `KeyboardEvent` up front, which always holds because it is only ever bound to `keydown`.
	 *
	 * @param event - The keydown event, narrowed to a `KeyboardEvent` for use.
	 */
	private onKeyDown = ( event: Event ): void => {
		if ( ! ( event instanceof KeyboardEvent ) ) {
			return;
		}

		if ( event.key === 'Escape' ) {
			if ( this.$interactiveTarget ) {
				this.$interactiveTarget.blur();
			}

			if ( this.isLocked ) {
				document.exitPointerLock();
			}
		}

		if ( this.isMovementKey( event.code ) ) {
			this.keys[ event.code ] = true;
		}
	};

	/**
	 * Clears a released movement key.
	 *
	 * The release clears unconditionally, unlike the gated keydown: a key still held when a form field takes focus would otherwise stay latched through {@link isMovementKey} returning false, and the gated loop would keep walking and rendering on a key the reader let go of long ago.
	 * The parameter is typed `Event` for the same render-root listener reason as {@link onKeyDown}, and narrowed to `KeyboardEvent` before use.
	 *
	 * @param event - The keyup event, narrowed to a `KeyboardEvent` for use.
	 */
	private onKeyUp = ( event: Event ): void => {
		if ( ! ( event instanceof KeyboardEvent ) ) {
			return;
		}

		if ( MOVEMENT_KEYS.has( event.code ) ) {
			this.keys[ event.code ] = false;
		}
	};

	/**
	 * Tracks whether pointer lock is held, using the render root so the check works inside the shadow boundary.
	 */
	private onPointerLockChange = (): void => {
		this.isLocked = this.root.pointerLockElement === this.$viewport;
	};

	/**
	 * Pauses or resumes the render loop as the demo scrolls in and out of view, so an offscreen room costs no frames.
	 *
	 * @param entries - The intersection records for the observed viewport.
	 */
	private onIntersection( entries: IntersectionObserverEntry[] ): void {
		for ( const entry of entries ) {
			this.isVisible = entry.isIntersecting;

			if ( this.isVisible ) {
				this.prevTime = performance.now();
				this.startLoop();
			} else {
				this.stopLoop();
			}
		}
	}

	/**
	 * Begins a drag-to-look gesture, focuses the viewport for keyboard walking, and lazily resolves the control mode on the first press in an embedded frame.
	 *
	 * Only the primary pointer's primary button starts a gesture: a right or middle click falls through to the browser, since a context menu can swallow the matching release and leave a phantom drag armed, and a gesture already in progress owns the viewport, so a new contact of any type is ignored until the owning pointer releases, because `isPrimary` is per pointer type and a first touch mid-mouse-drag would otherwise pass the guard and steal the gesture. The same contract lets a touch drag steer the fallback look, since the viewport already opts out of native panning with `touch-action: none`.
	 * The scene renders on load with no entry overlay, so the first press is where the room decides between captured pointer lock and the drag-look fallback: it requests pointer lock, and if the request is unavailable or denied it stays in drag-look, which is fully usable with the pointer held down plus WASD or the arrow keys.
	 * The handler calls `preventDefault` to suppress the native text selection and grab gesture, which also suppresses the implicit focus a press would give the canvas, so it focuses the viewport explicitly: without focus the render-root `keydown` listeners never fire in the embedded iframe, which is exactly why a click was needed before the keys would move the camera. The focus is taken with `preventScroll` so clicking into the scene never yanks the page to the demo.
	 *
	 * @param event - The pointerdown on the viewport.
	 */
	private onPointerDown = ( event: PointerEvent ): void => {
		if ( this.activePointerId !== null || ! event.isPrimary || event.button !== 0 ) {
			return;
		}

		this.isDragging = true;
		this.activePointerId = event.pointerId;
		this.lastPointer = { x: event.clientX, y: event.clientY };
		event.preventDefault();
		this.$viewport.focus( { preventScroll: true } );

		if ( this.controlMode === 'drag-look' && ! this.isLocked ) {
			this.tryPointerLock();
		}
	};

	/**
	 * Attempts pointer lock, upgrading the control mode when it lands and staying in drag-look when it is denied.
	 *
	 * Pointer lock is often blocked in an embedded iframe, so any rejection leaves the room in the drag-look fallback rather than failing.
	 */
	private tryPointerLock(): void {
		const request = this.$viewport.requestPointerLock();

		if ( request && typeof request.then === 'function' ) {
			request.then(
				() => {
					this.controlMode = 'pointer-lock';
				},
				() => {
					this.controlMode = 'drag-look';
				},
			);
			return;
		}

		// Older browsers return undefined from requestPointerLock; confirm the lock landed on the next tick, else stay in drag-look.
		window.setTimeout( () => {
			if ( this.root.pointerLockElement === this.$viewport ) {
				this.controlMode = 'pointer-lock';
			}
		}, 120 );
	}

	/**
	 * Ends the drag-look gesture when its owning pointer is released anywhere.
	 *
	 * Only the pointer that started the gesture can end it, so releasing an unrelated contact leaves a live drag alone; the `click` that follows the primary release still runs the crosshair-aim form flow on its own event, unchanged.
	 *
	 * @param event - The pointerup on the window.
	 */
	private onPointerUp = ( event: PointerEvent ): void => {
		if ( ! this.isDragging || event.pointerId !== this.activePointerId ) {
			return;
		}

		this.isDragging = false;
		this.activePointerId = null;
	};

	/**
	 * Abandons the drag-look gesture when the browser cancels the owning pointer, a touch scroll takeover or a system sheet, without treating the interruption as a look or a click.
	 *
	 * Only the gesture's own pointer can cancel it, so an unrelated contact being cancelled leaves a live drag alone.
	 */
	private onPointerCancel = ( event: PointerEvent ): void => {
		if ( event.pointerId !== this.activePointerId ) {
			return;
		}

		this.isDragging = false;
		this.activePointerId = null;
	};

	/**
	 * Applies look while pointer lock is held or an owned drag gesture is active.
	 *
	 * The two paths deliberately read different deltas. Free look under lock consumes the event's raw movement deltas, gated only on `isLocked`, because a captured cursor has no meaningful client position and the gesture fields stay untouched, which is the pointer-lock contract this handler preserves.
	 * Drag look is a real gesture, so it only follows the pointer that started it: the move is filtered by the owning pointer id, and the delta is measured between client samples, which keeps a second contact from steering and carries a touch drag where movement deltas are unreliable.
	 *
	 * @param event - The pointermove on the document, carrying the frame's movement or position delta.
	 */
	private onPointerMove = ( event: PointerEvent ): void => {
		if ( this.isLocked ) {
			this.applyLook( event.movementX, event.movementY );
			return;
		}

		if ( ! this.isDragging || event.pointerId !== this.activePointerId ) {
			return;
		}

		const dx = event.clientX - this.lastPointer.x;
		const dy = event.clientY - this.lastPointer.y;
		this.lastPointer = { x: event.clientX, y: event.clientY };
		this.applyLook( dx, dy );
	};

	/**
	 * Yaws and pitches the camera by a pixel delta, with pitch clamped just short of straight up or down so the view never flips, then marks the frame dirty so the gated loop draws the new angle.
	 *
	 * It is the one place both look paths land, so the sensitivity and the clamp cannot drift between pointer lock and drag look.
	 *
	 * @param dx - The horizontal look delta in pixels.
	 * @param dy - The vertical look delta in pixels.
	 */
	private applyLook( dx: number, dy: number ): void {
		if ( ! this.camera ) {
			return;
		}

		this.euler.setFromQuaternion( this.camera.quaternion );
		this.euler.y -= dx * this.lookSpeed;
		this.euler.x -= dy * this.lookSpeed;
		this.euler.x = Math.max( -Math.PI / 2 + 0.05, Math.min( Math.PI / 2 - 0.05, this.euler.x ) );
		this.camera.quaternion.setFromEuler( this.euler );
		this.requestRender();
	}

	/**
	 * Handles a crosshair-aim click: raycasts at screen center, and focuses the monitor form field under the hit.
	 *
	 * A click raycasts from screen center in both control modes, so aiming the camera at a field and clicking focuses it whether or not pointer lock is held.
	 */
	private onViewportClick = (): void => {
		if ( ! this.camera || ! this.monitorMesh ) {
			return;
		}

		this.raycaster.setFromCamera( new THREE.Vector2( 0, 0 ), this.camera );
		const hits = this.raycaster.intersectObject( this.monitorMesh, false );
		const hit = hits.length > 0 && hits[ 0 ].uv ? hits[ 0 ] : null;

		if ( this.$interactiveTarget ) {
			if ( hit && hit.uv && this.focusFormElement( hit.uv ) ) {
				this.updateInteractionHint();
				return;
			}

			this.$interactiveTarget.blur();
			this.$interactiveTarget = null;
			this.updateInteractionHint();
			return;
		}

		if ( hit && hit.uv && this.focusFormElement( hit.uv ) ) {
			this.updateInteractionHint();
		}
	};

	/**
	 * Focuses the monitor form control under a UV hit on the monitor mesh, or actions a button or select.
	 *
	 * The UV is converted to a pixel point in the staging canvas's layout box, then matched against the form's interactive children by their bounding rectangles, since the clipped staging container makes `elementFromPoint` unreliable.
	 * A submit button click and a select cycle are handled inline, and a text or email input is focused with its content selected, so the browser delivers keystrokes to it and typing replaces whatever was there.
	 *
	 * @param uv - The UV coordinate of the hit on the monitor mesh.
	 * @returns Whether a field was focused, as opposed to a one-shot action or a miss.
	 */
	private focusFormElement( uv: THREE.Vector2 ): boolean {
		const $staging = this.$monitorCanvas;
		const width = $staging.clientWidth || $staging.width;
		const height = $staging.clientHeight || $staging.height;
		const px = uv.x * width;
		const py = ( 1 - uv.y ) * height;

		const canvasRect = $staging.getBoundingClientRect();
		const $candidates = $staging.querySelectorAll<HTMLElement>( 'input, select, textarea, button' );
		let $target: HTMLElement | null = null;

		for ( const $element of $candidates ) {
			const rect = $element.getBoundingClientRect();
			const localX = rect.left - canvasRect.left;
			const localY = rect.top - canvasRect.top;

			if ( px >= localX && px < localX + rect.width && py >= localY && py < localY + rect.height ) {
				$target = $element;
				break;
			}
		}

		if ( ! $target ) {
			return false;
		}

		if ( $target instanceof HTMLButtonElement ) {
			$target.click();
			return false;
		}

		if ( $target instanceof HTMLSelectElement ) {
			const count = $target.options.length;

			if ( count > 0 ) {
				$target.selectedIndex = ( $target.selectedIndex + 1 ) % count;
				$target.dispatchEvent( new Event( 'change', { bubbles: true } ) );
				this.$monitorCanvas.requestPaint?.();
			}

			return false;
		}

		$target.focus( { preventScroll: true } );

		// The ray resolves a control, not a caret: mapping the hit to a character offset is more bridge than this research path earns, so existing text is selected instead, and typing replaces it while Backspace clears it.
		if ( $target instanceof HTMLInputElement ) {
			$target.select();
		}

		this.$interactiveTarget = $target;
		$target.addEventListener(
			'blur',
			() => {
				if ( this.$interactiveTarget === $target ) {
					this.$interactiveTarget = null;
				}

				this.updateInteractionHint();
			},
			{ once: true },
		);
		return true;
	}

	/**
	 * The persistent control reminder, written to match the control mode that actually resolved in this frame.
	 *
	 * The walking keys only fire once the scene holds keyboard focus, which the reader gives it by clicking or dragging into the room, so every variant leads with that click cue rather than letting the reader press WASD against a scene that has not been focused yet.
	 * On a build that grants pointer lock the cursor is captured on click, so while it is held the hint names the free-look mouse and tells the reader the one thing that is not obvious, that Escape releases the cursor and leaves the demo; once Escape frees the cursor the same build prompts that clicking re-captures it.
	 * The drag-look fallback keeps the held-button wording and needs no Escape, since the cursor was never captured.
	 *
	 * @returns The control hint copy for the current control state.
	 */
	private controlHintText(): string {
		if ( this.controlMode === 'pointer-lock' ) {
			if ( this.isLocked ) {
				return 'Move the mouse to look, WASD or arrows to move, click a field to type, Esc to free the cursor.';
			}

			return 'Click the scene to look around, then WASD or arrows to move, Esc frees the cursor again.';
		}

		return 'Click the scene first, then drag to look and walk with WASD or the arrow keys; aim at a field and click to type.';
	}

	/**
	 * Shows or hides the typing hint depending on whether a form field is focused, and marks the scene dirty.
	 *
	 * The hint itself is DOM chrome outside the canvas, but every call here is a focus handoff on the monitor, whose focus ring lands in the captured form, so the gated loop owes a frame to show the screen's new state.
	 */
	private updateInteractionHint(): void {
		this.requestRender();

		if ( this.$interactiveTarget ) {
			this.$interactionHint.textContent = 'Typing into the form, press Esc to release';
			this.$interactionHint.classList.add( 'visible' );
			return;
		}

		this.$interactionHint.classList.remove( 'visible' );
	}

	/**
	 * Resizes the renderer and updates the camera aspect when the viewport's CSS box changes, then marks the scene dirty so the gated loop redraws at the new size.
	 */
	private onResize(): void {
		if ( ! this.camera || ! this.renderer ) {
			return;
		}

		const size = this.viewportSize();
		this.camera.aspect = size.width / size.height;
		this.camera.updateProjectionMatrix();
		this.renderer.setSize( size.width, size.height, false );
		this.requestRender();
	}

	/**
	 * Watches the device pixel ratio through a query pinned to the current resolution, corrects the renderer, and rebuilds the one-shot listener for the next change.
	 *
	 * `matchMedia( '(resolution: Ndppx)' )` only watches the current ratio, so a move to a different-density display needs the query rebuilt each time; the renderer caps the ratio at two so a very dense display does not balloon the backing store.
	 */
	private observeDevicePixelRatio(): void {
		this.dprQuery?.removeEventListener( 'change', this.onDevicePixelRatioChange );
		const dpr = window.devicePixelRatio || 1;
		this.dprQuery = window.matchMedia( `(resolution: ${ dpr }dppx)` );
		this.dprQuery.addEventListener( 'change', this.onDevicePixelRatioChange, { once: true } );
		this.renderer?.setPixelRatio( Math.min( dpr, 2 ) );
	}

	/**
	 * Re-corrects the renderer after the device pixel ratio changes, then re-arms the watcher and marks the scene dirty through the resize path.
	 */
	private onDevicePixelRatioChange = (): void => {
		this.observeDevicePixelRatio();
		this.onResize();
	};

	/**
	 * Starts the timer that keeps the monitor form repainting on the live path.
	 *
	 * `requestPaint` only does work on the live path, so the timer is cheap when the experimental API is absent: a slow idle repaint keeps the texture fresh, and a fast repaint while a field is focused makes the caret and live text show up promptly in the scene.
	 */
	private startContentTimers(): void {
		this.timers.push( window.setInterval( () => this.$monitorCanvas.requestPaint?.(), 2000 ) );
		this.timers.push(
			window.setInterval( () => {
				if ( this.$interactiveTarget ) {
					this.$monitorCanvas.requestPaint?.();
				}
			}, 100 ),
		);
	}

	/**
	 * Advances the camera from the held movement keys, clamped to the room and blocked from walking into the desk.
	 *
	 * Movement runs whenever the room is on screen, so the reader can walk with the keyboard the moment the scene loads, with or without pointer lock.
	 *
	 * @param dt - The elapsed time since the previous frame, in seconds.
	 */
	private updateMovement( dt: number ): void {
		if ( ! this.camera ) {
			return;
		}

		const forward = new THREE.Vector3( 0, 0, -1 ).applyQuaternion( this.camera.quaternion );
		forward.y = 0;
		forward.normalize();

		const right = new THREE.Vector3( 1, 0, 0 ).applyQuaternion( this.camera.quaternion );
		right.y = 0;
		right.normalize();

		const velocity = new THREE.Vector3();

		if ( this.keys.KeyW || this.keys.ArrowUp ) {
			velocity.add( forward );
		}

		if ( this.keys.KeyS || this.keys.ArrowDown ) {
			velocity.sub( forward );
		}

		if ( this.keys.KeyD || this.keys.ArrowRight ) {
			velocity.add( right );
		}

		if ( this.keys.KeyA || this.keys.ArrowLeft ) {
			velocity.sub( right );
		}

		if ( velocity.lengthSq() === 0 ) {
			return;
		}

		velocity.normalize().multiplyScalar( this.moveSpeed * dt );
		const next = this.camera.position.clone().add( velocity );

		const margin = 0.4;
		next.x = Math.max( -HALF_W + margin, Math.min( HALF_W - margin, next.x ) );
		next.z = Math.max( -HALF_D + margin, Math.min( HALF_D - margin, next.z ) );

		if ( next.z < -3.0 && Math.abs( next.x ) < 1.7 ) {
			next.z = Math.max( next.z, -3.0 );
		}

		this.camera.position.copy( next );
	}

	/**
	 * Starts the render loop if it is not already running and the demo is on screen, and marks the scene dirty so the first frame back repaints.
	 */
	private startLoop(): void {
		if ( this.frame === 0 && this.isVisible ) {
			this.frame = requestAnimationFrame( this.renderLoop );
		}

		this.requestRender();
	}

	/**
	 * Stops the render loop and clears the frame handle so it can be restarted cleanly.
	 */
	private stopLoop(): void {
		if ( this.frame !== 0 ) {
			cancelAnimationFrame( this.frame );
			this.frame = 0;
		}
	}

	/**
	 * Marks the scene dirty so the next animation frame runs the movement step, the texture upload, and the render.
	 */
	private requestRender(): void {
		this.needsRender = true;
	}

	/**
	 * Whether any movement key is currently held, checked by the loop each frame because a held key streams no events to mark dirty from.
	 *
	 * @returns Whether a held key should keep the loop rendering.
	 */
	private hasMovementInput(): boolean {
		for ( const code of MOVEMENT_KEYS ) {
			if ( this.keys[ code ] ) {
				return true;
			}
		}

		return false;
	}

	/**
	 * The render loop: advances movement, syncs the live monitor surface into its texture, and draws the frame.
	 *
	 * The loop stays hot at the frame cadence while the demo is on screen, but the work is gated on {@link needsRender}: an idle frame re-arms itself, advances the clock, and returns, so a room nobody is walking or looking around renders nothing, and the first frame after a change does the full pass.
	 * Held movement keys mark the frame dirty here rather than from an event, since a key held down streams nothing between keydown and keyup, and the clock advances on idle frames too so the first dirty frame after a pause steps by one frame rather than the whole pause.
	 */
	private renderLoop = (): void => {
		this.frame = requestAnimationFrame( this.renderLoop );

		if ( ! this.renderer || ! this.scene || ! this.camera ) {
			return;
		}

		const now = performance.now();
		const dt = Math.min( ( now - this.prevTime ) / 1000, 0.1 );
		this.prevTime = now;

		if ( this.hasMovementInput() ) {
			this.requestRender();
		}

		if ( ! this.needsRender ) {
			return;
		}

		this.needsRender = false;
		this.updateMovement( dt );

		for ( const surface of this.surfaces ) {
			surface.mirrorCtx.clearRect( 0, 0, surface.mirror.width, surface.mirror.height );
			surface.mirrorCtx.drawImage( surface.staging, 0, 0 );
			surface.texture.needsUpdate = true;
		}

		this.renderer.render( this.scene, this.camera );
	};

	/**
	 * Renders the viewport, the crosshair and hints, and the clipped staging canvas that hosts the live sign-up form.
	 *
	 * The staging markup is identical across both paths so the experimental draw has real DOM to capture; the mode note is the one piece that changes, naming whether the monitor is live or a static rendering.
	 */
	render() {
		const live = this.textureMode === 'live';

		return html`
			<canvas
				class="viewport"
				role="img"
				tabindex="0"
				aria-label="A navigable 3D office with a monitor showing a sign-up form. Click the scene, then walk with WASD or the arrow keys."
			></canvas>

			<div class="control-hint">${ this.controlHintText() }</div>

			<div class="crosshair"></div>
			<div class="interaction-hint"></div>

			<div class="mode-note">
				${ live
					? html`<span class="hl">Live.</span> The monitor is our real sign-up form, captured into a <code>CanvasTexture</code> every frame. Aim and click a field to type.`
					: html`The monitor shows a static rendering of our form. The live, focusable form needs the flag at <code>chrome://flags/#canvas-draw-element</code>; the room stays navigable either way.` }
			</div>

			<!--
				The staging form is an offscreen texture-capture source, not an operable surface. It is aria-hidden so the captured DOM is not double-exposed in the accessibility tree, and every control carries tabindex="-1" so a keyboard Tab cannot land on this 1px clipped form. The bridge still focuses fields programmatically via target.focus() and activates buttons via .click(), and the browser delivers keystrokes and runs native validation and submit on the focused input, so removing the controls from the tab order leaves the research interaction bridge working. This is the deliberate, proportionate choice for a Research-tier demo of texture capture plus hand-written keyboard delivery, not accessible 3D interaction.
			-->
			<div class="staging-container" aria-hidden="true">
				<canvas class="staging monitor-canvas" width="760" height="488">
					<div class="monitor-content">
						<div class="monitor-inner">${ this.renderMonitorForm() }</div>
					</div>
				</canvas>
			</div>
		`;
	}

	/**
	 * Renders the on-monitor form, or the local confirmation once a valid submit has happened.
	 *
	 * The markup is the room's own plain-DOM form, a name input, an email input, a topic select, and a submit, with native `required` and `type="email"` validation, so the drawn screen is a real control rather than a redraw.
	 * The text fields start empty with placeholder examples, so anything in them is the reader's own typing and native `required` validation has something honest to catch on submit.
	 * The confirmation is rendered in place with no network, the way submitting the flat form yields its own confirmation, which is how the demo proves the drawn screen is real interactive HTML.
	 */
	private renderMonitorForm() {
		if ( this.submitted ) {
			return html`
				<div class="monitor-confirm">
					<h3>Configuration saved</h3>
					<dl>
						<dt>Name</dt>
						<dd>${ this.submitted.name }</dd>
						<dt>Email</dt>
						<dd>${ this.submitted.email }</dd>
						<dt>Topic</dt>
						<dd>${ this.submitted.topic }</dd>
					</dl>
					<button type="button" class="monitor-again" tabindex="-1" @click=${ this.onResetForm }>Configure another</button>
				</div>
			`;
		}

		return html`
			<div class="monitor-eyebrow">Sign up</div>
			<h3 class="monitor-title">Drop us a note</h3>
			<form class="monitor-form" @submit=${ this.onMonitorSubmit }>
				<div class="monitor-field">
					<label for="monitor-name">Your name</label>
					<input id="monitor-name" name="name" type="text" required autocomplete="off" tabindex="-1" placeholder="Jane Doe" />
				</div>
				<div class="monitor-field">
					<label for="monitor-email">Email</label>
					<input id="monitor-email" name="email" type="email" required autocomplete="off" tabindex="-1" placeholder="jane@example.com" />
				</div>
				<div class="monitor-field">
					<label for="monitor-topic">What is on your mind?</label>
					<select id="monitor-topic" name="topic" tabindex="-1">
						<option value="HTML-in-Canvas feedback">HTML-in-Canvas feedback</option>
						<option value="A demo idea">A demo idea</option>
						<option value="Just saying hi">Just saying hi</option>
					</select>
				</div>
				<button class="monitor-submit" type="submit" tabindex="-1">Save configuration</button>
				<div class="monitor-fineprint">A real form, drawn onto a monitor. No network, nothing leaves the page.</div>
			</form>
		`;
	}

	/**
	 * Shows the local confirmation when the monitor form passes native validation, with no network, then repaints the surface.
	 *
	 * The native `submit` event already gates on the `required` and email constraints, so reaching this handler means the fields are well-formed.
	 *
	 * @param event - The monitor form's native submit event.
	 */
	private onMonitorSubmit = ( event: SubmitEvent ): void => {
		event.preventDefault();

		const $form = event.currentTarget;
		if ( ! ( $form instanceof HTMLFormElement ) ) {
			return;
		}

		const data = new FormData( $form );
		this.submitted = {
			name: String( data.get( 'name' ) ?? '' ),
			email: String( data.get( 'email' ) ?? '' ),
			topic: String( data.get( 'topic' ) ?? '' ),
		};

		this.$monitorCanvas.requestPaint?.();
	};

	/**
	 * Clears the confirmation and returns to the empty form, so the demo can be run again without a reload, then repaints the surface.
	 */
	private onResetForm = (): void => {
		this.submitted = null;
		this.$monitorCanvas.requestPaint?.();
	};
}

